    "pub_date": "2026-08-04 06:10:16",
    "author": "",
    "description": "新华社东京8月3日电(记者陈泽安 冯武勇)据日本共同社报道，熊本县熊本市中央区和熊本县菊池市3日分别记录到40.3摄氏度和40.2摄氏度的气温，这是该县首次测得40摄氏度以上的气温。熊本县此前遭遇7.1级地震，当前仍面临大范围停水，超过8000人在避难所避难。",
    "content": "新华社东京8月3日电(记者陈泽安 冯武勇)据日本共同社报道，熊本县熊本市中央区和熊本县菊池市3日分别记录到40.3摄氏度和40.2摄氏度的气温，这是该县首次测得40摄氏度以上的气温。熊本县此前遭遇7.1级地震，当前仍面临大范围停水，超过8000人在避难所避难。"
