    "author": "",
    "description": "根据中央气象台的消息，未来几天，35℃以上的高温天气主要分布在我国东西两片区域。其中，新疆、内蒙古西部以干热暴晒为主。江南、江淮至黄淮、华北南部、东北地区一带，则闷热感突出。东北地区等地未来几天可能出现同期少见甚至破纪录的高温天气，公众需持续做好防暑降温工作。",
    "content": "根据中央气象台的消息，未来几天，35℃以上的高温天气主要分布在我国东西两片区域。其中，新疆、内蒙古西部以干热暴晒为主。江南、江淮至黄淮、华北南部、东北地区一带，则闷热感突出。东北地区等地未来几天可能出现同期少见甚至破纪录的高温天气，公众需持续做好防暑降温工作。"
