    "author": "廖军华/央视新闻",
    "description": "8月3日，西班牙北非飞地休达，从摩洛哥入境的移民聚集在海滩上。 当地时间8月3日，西班牙警方表示，约7.35万名移民已从北非自治市休达返回摩洛哥。目前，休达社会秩序正逐步恢复，当地商铺已陆续恢复营业。 警方同时表示，此次移民危机中已有88名试图游泳进入休达的非法移民死亡。",
    "content": "8月3日，西班牙北非飞地休达，从摩洛哥入境的移民聚集在海滩上。 当地时间8月3日，西班牙警方表示，约7.35万名移民已从北非自治市休达返回摩洛哥。目前，休达社会秩序正逐步恢复，当地商铺已陆续恢复营业。 警方同时表示，此次移民危机中已有88名试图游泳进入休达的非法移民死亡。"
