    "content": "快科技8月4日消息，据央视新闻“总台环球资讯广播”报道， 欧洲能源格局迎来重大转折，唯一没有运营核电站的G7国家意大利，正式推进核电重启立法，此时距离该国全面淘汰核电已经过去40年 。 意大利早在上世纪建成四座商用核电站，是欧洲核电先行者，但1986年切尔诺贝利事故引爆民众恐慌，1987年全民公投决定弃核，1990年国内最后两座反应堆永久关停，2011年日本福岛事故后，重启核电计划再度被全民公投否决。 2023年欧洲能源危机推高电价，意大利正式重启核电系统性规划，但推进相当缓慢，直到今年6月，众议院率先通过核电授权…"
