    "description": "作为一个古早码农，sublime text 一直是我的心头好。虽然这两年使用它的频次迅速下滑... 当初 codeium “横空出世”时，我一度觉得它是我最喜欢的 sublime 插件之一。我甚至为它卸载了 LSP 类插件。就这么用着，一直到最近突然发现“终于不能用了”——其实看着它一路从 codeium 变成 windsurf 再变成 devin 我就隐隐觉得用不长久了。 这两天一开始尝试了好几款其他插件，什么 Tabnine 、Co…",
    "content": "作为一个古早码农，sublime text 一直是我的心头好。虽然这两年使用它的频次迅速下滑... 当初 codeium “横空出世”时，我一度觉得它是我最喜欢的 sublime 插件之一。我甚至为它卸载了 LSP 类插件。就这么用着，一直到最近突然发现“终于不能用了”——其实看着它一路从 codeium 变成 windsurf 再变成 devin 我就隐隐觉得用不长久了。 这两天一开始尝试了好几款其他插件，什么 Tabnine 、CodeContinue 等，感觉都没有 codeium 好用。苦恼之下尝试问 AI…"
