    "content": "新华社东京8月3日电（记者陈泽安 冯武勇）据日本共同社报道，熊本县熊本市中央区和熊本县菊池市3日分别记录到40.3摄氏度和40.2摄氏度的气温，这是该县首次测得40摄氏度以上的气温。熊本县此前遭遇7.1级地震，当前仍面临大范围停水，超过8000人在避难所避难。 7月28日，熊本县发生7.1级地震。目前，与地震灾害有关联的死亡人数已达38人，当地仍有约4.5万户停水，8262人栖身在熊本县的155个避难所，还有一些人在车内过夜。 连日来，当地高温天气持续。据熊本县2日通报，一名地震发生后在车内避难过夜的女性疑因中暑死…"
