    "content": "新华社马普托8月3日电（记者刘杰）中国援莫桑比克国家外科中心项目奠基仪式3日在莫桑比克首都马普托举行。出席仪式的莫桑比克总统查波致辞说，该项目将成为莫中两国公共卫生领域合作的重要标志。 查波说，数十年来，莫中两国建立了牢固的伙伴关系，这一关系建立在相互尊重、政治互信基础上。中国援莫桑比克国家外科中心项目将为成千上万的莫桑比克家庭带来福祉，更多莫桑比克民众将能够在自己的国家获得所需的专科医疗服务。 中国驻莫桑比克大使郑璇说，中国始终坚持把人民健康放在重要位置，也始终高度重视支持莫桑比克医疗卫生事业发展。从派遣中国医疗…"
