    "content": "IT之家 8 月 3 日消息，意大利曾是欧洲发展核电的先驱，但 1986 年切尔诺贝利核事故后，意大利于 1987 年经过公投，决定全面关停核电项目。据央视新闻“总台环球资讯广播”今日报道，这一局面有望迎来改变。 意大利议会预计将于近期审议政府提交的法案，为新一代核能技术搭建法律框架 。 报道提到，意大利电力进口依赖度高、用电成本居高不下，能源自主需求持续攀升。今年以来，梅洛尼政府正式推动核电立法，计划将核电重新纳入国家能源供给体系。 意大利环境与能源安全部长吉尔贝托 · 皮凯托 · 弗拉廷公布了计划中的项目建设与…"
