    "author": "yeekal",
    "description": "similarweb 流量很多网站，比如导航站都在用，但是它的 api 挺贵的，推测大家并没有都是付了钱的吧 是不是有逆向接口的捷径 我现在让 gpt 帮我逆向了一个出来，利用了 apify 平台的代理 ip 接口，使用 playwright 无头浏览器，目前大概 2$/千次域名查询 感觉还是有点贵 有没有好的方案，不为人知的超实惠的 api",
    "content": "similarweb 流量很多网站，比如导航站都在用，但是它的 api 挺贵的，推测大家并没有都是付了钱的吧 是不是有逆向接口的捷径 我现在让 gpt 帮我逆向了一个出来，利用了 apify 平台的代理 ip 接口，使用 playwright 无头浏览器，目前大概 2$/千次域名查询 感觉还是有点贵 有没有好的方案，不为人知的超实惠的 api"
