    "content": "急症室里，医护人员正在全力抢救一位癌症晚期的病人。 起初，所有人都以为这只是一次寻常的夜间急救，没有人意识到，在接下来不到 10 分钟的时间里，这位躺在病床上，生命垂危的病人，会以一种诡异的方式， 毒晕在场的 23 名医护，其中 5 人住院治疗，还有 1 人在 ICU 里躺了两周，后续还出现胰腺炎，膝部缺血性坏死等严重后遗症。 这位患者，也从此被冠上“毒妇（Toxic Lady）”的称号，给全世界的法医和科学家留下一道数十年难解的谜题。 而最接近真相的答案竟然和一种在实验室里我们每天都要接触，甚至被认为相对安全的物…"
