    "author": "",
    "description": "Getty Images / 不再“买买买”：为何中国消费者开始省钱过日子？ 中国以生产全球热销商品闻名，但在国内，消费者的支出却远低于政府的期待。 房地产市场低迷、青年失业率居高不下，以及消费信心疲弱，使许多家庭选择储蓄而非消费，也让中国更难摆脱依赖出口的经济模式。 中国政府已推出一系列刺激消费措施，包括发放消费补贴，以及公布扩大消费的五年规划。 然而，为何这些政策未能达到北京预期的效果？中国消费低迷究竟只是短期现象，还是反映出更深层…",
    "content": "Getty Images / 不再“买买买”：为何中国消费者开始省钱过日子？ 中国以生产全球热销商品闻名，但在国内，消费者的支出却远低于政府的期待。 房地产市场低迷、青年失业率居高不下，以及消费信心疲弱，使许多家庭选择储蓄而非消费，也让中国更难摆脱依赖出口的经济模式。 中国政府已推出一系列刺激消费措施，包括发放消费补贴，以及公布扩大消费的五年规划。 然而，为何这些政策未能达到北京预期的效果？中国消费低迷究竟只是短期现象，还是反映出更深层的结构性问题？"
