    "content": "中央气象台3日预报，今年第13号台风“白海豚”目前位于西北太平洋洋面，预计6日至7日将穿过琉球群岛移入东海，影响我国。公众需持续关注最新预报预警信息，提前做好台风防御准备。 中央气象台预计，“白海豚”5日之前对我国无明显影响，6日至7日将穿过琉球群岛移入东海，之后其移动路径和对我国的影响不确定性较大，目前研判主要有两种路径可能影响我国。 一种可能是“白海豚”在东海西行趋向长江口以南沿海。9日前后，“白海豚”在长江口到福建北部沿海登陆（台风级或强台风级），登陆后继续向偏西方向移动，深入内陆。这种情况的登陆，影响时间最…"
