    "content": "据新华社，7月31日凌晨3时50分许，内蒙古自治区乌兰察布市卓资县中铁建压缩空气储能项目中铁十五局负责施工的隧道标段发生塌方事故，造成4人遇难、6人受伤。截至当日12时，现场救援工作已经结束，受伤人员已全部送往医疗机构救治，伤情平稳。事故相关责任人已被控制，善后工作正在有序开展，内蒙古自治区政府已成立调查组，开展事故调查。 公开资料显示，乌兰察布现有两个压缩空气储能项目。其中，位于化德县、由三峡新能源投资建设的60兆瓦/240兆瓦时电站已于去年9月并网发电。目前仍在建的是卓资县105万千瓦/630万千瓦时压缩空气储…"
