    "content": "新华社北京8月3日电 题：新型电力系统建设迎来“十五五”发展路线图 新华社记者王悦阳、魏玉坤 8月3日，国家发展改革委、国家能源局发布《新型电力系统建设“十五五”规划》，明确未来五年我国电力发展的总体思路，提出到2030年初步建成新型电力系统的战略目标，部署电力行业发展的主要目标、重大工程、重点任务。 “十五五”期间，随着算力用电激增，电动汽车充电需求快速增加，以及其他行业和居民生活用电刚性增长，预计全国年均用电增量将达到6000亿度左右，相当于每年新增一个中等经济体量国家的用电水平。 “规划深入落实加快构建清洁低…"
