    "author": "罗新才（摄制）,何春好",
    "description": "8月初，云南省大理白族自治州洱源县连天阴雨，云南省自然资源厅驻县工程师杜超和同事要确保每一处灾害监测设备正常运行。 杜超介绍：“地质灾害监测预警设备是我们的第一道防线，也就像我们的耳朵、眼睛一样。” 这些“眼睛”是484套监测预警设备，安装在76个重点隐患点上。滑坡体上有裂缝计和地表位移监测计，泥石流沟里有泥位计，村庄里有预警广播覆盖。当数据达到预警阈值，信息会实时推送各级平台和一线监测员手机。 洱源县凤羽镇铁甲村地质灾害监测员张小灿说…",
    "content": "8月初，云南省大理白族自治州洱源县连天阴雨，云南省自然资源厅驻县工程师杜超和同事要确保每一处灾害监测设备正常运行。 杜超介绍：“地质灾害监测预警设备是我们的第一道防线，也就像我们的耳朵、眼睛一样。” 这些“眼睛”是484套监测预警设备，安装在76个重点隐患点上。滑坡体上有裂缝计和地表位移监测计，泥石流沟里有泥位计，村庄里有预警广播覆盖。当数据达到预警阈值，信息会实时推送各级平台和一线监测员手机。 洱源县凤羽镇铁甲村地质灾害监测员张小灿说：“现在有这么多设备，但我们还是要实地去看，看完我们心里才踏实。” 凤羽镇铁甲村…"
