    "content": "新华社昆明8月3日电（记者熊轩昂）云南省宣威市尼珠河大峡谷内，垂直高度288米的二号悬崖电梯“扶摇梯”近日正式投运，与2022年投用、高268米的“青云梯”并肩矗立，搭配一段高空缆车，将山乡学子单程3个多小时的求学路缩减至30分钟，托举起峡谷里孩子们的云端求学路。 “我们有新的校车啦！”扶摇梯投运首日，尼珠河村小学生王娇牵着妹妹走进轿厢。轿厢以每秒5米的速度平稳攀升，脚下溪流化作细长银线，山间云海徐徐铺展。 宣威市普立乡尼珠河村坐落在尼珠河大峡谷谷底，地处云南省与贵州省交界，500余米垂直落差将谷底尼珠河村与谷顶的…"
