    "content": "新华社北京8月3日电 记者8月3日从国家能源局获悉，国家发展改革委、国家能源局日前印发《新型电力系统建设“十五五”规划》，明确未来五年我国电力发展的总体思路，提出到2030年初步建成新型电力系统的战略目标，部署电力行业发展的主要目标、重大工程、重点任务。 到2030年，非化石能源发电量占比达到50%，实现28亿千瓦以上新能源高水平消纳，建成可支撑超过1.1亿辆电动汽车出行的充电基础设施网络……规划提出一系列目标指标。 聚焦目标指标，规划部署重点任务，即加快形成绿色低碳的电力供给格局，着力构建主配微协同的新型电网，促…"
