    "content": "新华社巴库8月3日电（记者钟忠）第比利斯消息：格鲁吉亚总理科巴希泽日前表示，格中关系今年提升为全面战略伙伴关系，为两国进一步扩大政治和经济合作创造了新机遇。 科巴希泽在第比利斯举行的庆祝中国人民解放军建军99周年暨大使离任招待会上说，中国目前是格鲁吉亚第三大贸易伙伴，也是格鲁吉亚本国产品出口的第二大市场。两国实行互免签证、扩大直航并开通第比利斯至上海航线，为促进旅游、商务和投资合作提供了有利条件。 科巴希泽对中国致力于国际合作与维护稳定表示赞赏。他说：“和平与稳定在我们两国关系的诸多原则中占据特殊地位，中国在这方面…"
