    "content": "新华社香港8月3日电（记者肖逸晨）第十九届香港青少年军事夏令营暨第十三届香港大学生军事生活体验营，3日下午在中国人民解放军驻香港部队新围军营举行开营仪式。约500名香港青少年学生入营。 本届军事夏令营和军事生活体验营合并举办、同步组织，计划16日结业，入营学生将在军营进行为期14天的学习、训练、生活。活动期间，驻香港部队将聚焦爱国主义和国防教育主题，突出军营文化特色，结合香港青少年实际，安排军事训练、教育讲座、参观见学等系列活动，让香港青少年在丰富的训练和教育活动中深化对国家、军队的认识了解，培养守纪自律、团结协作…"
